## Patterns to follow

**The hook to generalise (`pages/Terminals.tsx:46-59`, current code):**
```typescript
const NARROW = "(max-width: 899.98px)";

function useNarrow(): boolean {
  const query = () => (typeof window.matchMedia === "function" ? window.matchMedia(NARROW) : undefined);
  const [narrow, setNarrow] = useState(() => query()?.matches ?? false);
  useEffect(() => {
    const mq = query();
    if (!mq) return;
    const on = () => setNarrow(mq.matches);
    on();
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return narrow;
}
```
`useMedia(query)` is this with `query` as a parameter and in the effect's dependency list. It must return `false` when `window.matchMedia` is missing (jsdom has none), so every existing test keeps its desktop behaviour.

**Test file header and matchMedia stub (`ui/theme.test.ts:1-15`):**
```typescript
// @vitest-environment jsdom
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

function stubMatchMedia(dark: boolean) {
  vi.stubGlobal(
    "matchMedia",
    vi.fn((query: string) => ({
      matches: dark && query === "(prefers-color-scheme: dark)",
      media: query,
      addEventListener: () => {},
      removeEventListener: () => {},
    })),
  );
}
afterEach(() => { vi.unstubAllGlobals(); vi.restoreAllMocks(); });
```
Tests opt into jsdom with the first-line comment `// @vitest-environment jsdom` (vitest.config.ts has no global environment). Hooks are tested with `renderHook` and `act` from `@testing-library/react` (v16, React 19).

**CSS comment style:** one short `/* … */` line above each block, as in `Shell.css:74` (`/* Rail: icons only, counts become dots. */`). Only `var(--…)` tokens for colours in `ui/base.css`.

## Step-by-step tasks

### CREATE `apps/graph-manager/src/web/ui/media.ts`

- **IMPLEMENT**:
  ```typescript
  import { useEffect, useState } from "react";

  /** The one narrow breakpoint of the app: below it the nav is a top bar + drawer and Terminals shows one pane. */
  export const NARROW = "(max-width: 899.98px)";
  /** Phones: tables become cards below it. */
  export const PHONE = "(max-width: 599.98px)";
  /** A touch screen (phone, tablet): big hit areas, extra terminal keys. Not decided by width. */
  export const COARSE = "(pointer: coarse)";

  const mql = (query: string) => (typeof window !== "undefined" && typeof window.matchMedia === "function" ? window.matchMedia(query) : undefined);

  /** True while `query` matches; follows `change` events. False when matchMedia is missing (jsdom). */
  export function useMedia(query: string): boolean {
    const [matches, setMatches] = useState(() => mql(query)?.matches ?? false);
    useEffect(() => {
      const mq = mql(query);
      if (!mq) { setMatches(false); return; }
      const on = () => setMatches(mq.matches);
      on();
      mq.addEventListener?.("change", on);
      return () => mq.removeEventListener?.("change", on);
    }, [query]);
    return matches;
  }
  ```
- **GOTCHA**: keep the optional-call `addEventListener?.` — some test stubs (e.g. `Settings.test.tsx:12`) return objects where it is a `vi.fn()`, others omit it.
- **VALIDATE**: `cd apps/graph-manager && npx tsc -p tsconfig.web.json --noEmit`

